using System; using System.Drawing; using System.Net.Sockets; using System.Windows.Forms; using WinInput.Shared;
namespace WinInput.Sender { public class MainForm:Form { TextBox host=new TextBox{Text="127.0.0.1"},port=new TextBox{Text="18765"},secret=new TextBox{UseSystemPasswordChar=true},text=new TextBox{Multiline=true}; Button connect=new Button{Text="连接"},send=new Button{Text="发送文字"}; TcpClient client; System.IO.Stream stream;
public MainForm(){Text="WinInput 发送端";ClientSize=new Size(520,300);var p=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(10),ColumnCount=2,RowCount=7};p.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,90));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100)); Add(p,"接收端地址",host,0);Add(p,"端口",port,1);Add(p,"共享密钥",secret,2);Add(p,"文字",text,3);p.Controls.Add(connect,0,4);p.Controls.Add(send,1,4);var keys=new FlowLayoutPanel{Dock=DockStyle.Fill};foreach(var k in new[]{"SHIFT+F1","CTRL+F1","ALT+F1","SHIFT+F2","CTRL+F2","ALT+F2","SHIFT+F3","CTRL+F3","ALT+F3","SHIFT+F4","CTRL+F4","ALT+F4","SHIFT+F5","CTRL+F5","ALT+F5","SHIFT+F6","CTRL+F6","ALT+F6","SHIFT+F7","CTRL+F7","ALT+F7","SHIFT+F8","CTRL+F8","ALT+F8","SHIFT+F9","CTRL+F9","ALT+F9","SHIFT+F10","CTRL+F10","ALT+F10","SHIFT+F11","CTRL+F11","ALT+F11","SHIFT+F12","CTRL+F12","ALT+F12"}){var b=new Button{Text=k,AutoSize=true};b.Click+=(s,e)=>Send("key",((Button)s).Text);keys.Controls.Add(b);}p.Controls.Add(keys,0,5);p.SetColumnSpan(keys,2);Controls.Add(p);connect.Click+=Connect;send.Click+=(s,e)=>Send("text",text.Text);send.Enabled=false;FormClosing+=(s,e)=>client?.Close();}
void Add(TableLayoutPanel p,string l,Control c,int r){p.Controls.Add(new Label{Text=l,AutoSize=true},0,r);c.Dock=DockStyle.Fill;p.Controls.Add(c,1,r);}void Connect(object s,EventArgs e){try{client=new TcpClient();client.Connect(host.Text,int.Parse(port.Text));stream=client.GetStream();connect.Text="已连接";connect.Enabled=false;send.Enabled=true;}catch(Exception x){MessageBox.Show(x.Message);}}void Send(string c,string v){try{Protocol.Write(stream,secret.Text,c,v);}catch(Exception x){MessageBox.Show(x.Message);}}
} }